// SSO-2969 — shared renderer for the per-recipe E2E_RESULTS.md file.
//
// ONE source of truth for the results-markdown shape, imported by BOTH:
//   • e2e/lib/e2e-results-reporter.mjs — the Playwright reporter that regenerates the
//     file from a LIVE run (pass/fail, timestamps, CI links, diagnostics), and
//   • e2e/scripts/init-e2e-results.mjs — the generator that writes the honest
//     "NOT YET RUN in this environment" file for a recipe that has never run here.
//
// Keeping the render in one place means the committed placeholder and the
// CI-regenerated file are the same document with the live fields filled in, so a
// reader browsing a recipe always sees the same sections (coverage, scenario,
// steps, latest result) whether or not a real run has happened yet.

/** A single status → emoji/word badge. */
function badge(status) {
  switch (status) {
    case "passed":
      return "✅ passed";
    case "failed":
      return "❌ failed";
    case "timedOut":
      return "⏱️ timed out";
    case "skipped":
      return "⏭️ skipped";
    case "interrupted":
      return "🚫 interrupted";
    case "pending":
      return "⏳ not yet run";
    default:
      return status ? `\`${status}\`` : "—";
  }
}

/** Escape a string for a single Markdown table cell. */
function cell(s) {
  return String(s ?? "")
    .replace(/\|/g, "\\|")
    .replace(/\r?\n/g, " ");
}

/**
 * Render the E2E_RESULTS.md body.
 *
 * @param {{
 *   recipeId: string,
 *   scenario: { title?: string, summary?: string, steps?: Array<{key:string,title:string}>, errorPath?: {title:string} },
 *   workflow?: string,
 *   overall: string,            // "passed" | "failed" | ... | "pending"
 *   counts?: { passed?: number, failed?: number, skipped?: number, total?: number },
 *   steps?: Array<{ title: string, status: string }>,   // declared steps annotated with live status
 *   tests?: Array<{ title: string, status: string, durationMs?: number }>,
 *   diagnostics?: string[],     // short error excerpts
 *   env?: Record<string,string>,
 *   links?: Array<{ label: string, url: string }>,
 *   generatedAt: string,        // ISO timestamp
 *   generatedBy: string,        // "the Playwright reporter" | "the init generator"
 *   live: boolean,              // true => a real run produced this; false => placeholder
 * }} data
 * @returns {string}
 */
export function renderResultsMarkdown(data) {
  const {
    recipeId,
    scenario = {},
    workflow,
    overall,
    counts = {},
    steps = [],
    tests = [],
    diagnostics = [],
    env = {},
    links = [],
    generatedAt,
    generatedBy,
    live,
  } = data;

  const out = [];
  out.push(`# E2E results — \`${recipeId}\``);
  out.push("");
  out.push(
    "<!-- GENERATED FILE — do not edit by hand. Regenerated by the shared Playwright",
  );
  out.push(
    "     reporter (e2e/lib/e2e-results-reporter.mjs) on every live run, and seeded by",
  );
  out.push("     e2e/scripts/init-e2e-results.mjs (`npm run results:init`). -->");
  out.push("");

  // Coverage + latest-result banner — the first thing a browser of the recipe sees.
  out.push(`**E2E coverage:** yes — colocated at [\`e2e/\`](./e2e/).`);
  if (workflow) {
    out.push(`**Runs in CI via:** \`${workflow}\` (nightly + \`workflow_dispatch\`).`);
  }
  out.push(`**Latest result:** ${badge(overall)}`);
  if (live && (counts.total ?? 0) > 0) {
    out.push(
      `**Tests:** ${counts.passed ?? 0} passed · ${counts.failed ?? 0} failed · ${counts.skipped ?? 0} skipped (of ${counts.total}).`,
    );
  }
  out.push(`**Generated:** ${generatedAt} — by ${generatedBy}.`);
  if (!live) {
    out.push("");
    out.push(
      "> This is the seeded placeholder. It has **not yet run in this environment**; the",
    );
    out.push(
      "> live journey runs against the staging SaaS in CI (needs the provisioned standing",
    );
    out.push(
      "> workspace + API key — see the repo `README.md`). The first live run overwrites",
    );
    out.push("> this file with real pass/fail, timings, diagnostics, and a CI run link.");
  }
  out.push("");

  // Scenario — what behaviour is tested.
  out.push("## Scenario");
  out.push("");
  if (scenario.title) out.push(`**${scenario.title}**`);
  if (scenario.summary) {
    out.push("");
    out.push(scenario.summary);
  }
  out.push("");

  // Steps — the major journey legs, annotated with live status when available.
  if (steps.length > 0) {
    out.push("## Steps / assertions");
    out.push("");
    out.push("| # | Step | Result |");
    out.push("|---|------|--------|");
    steps.forEach((s, i) => {
      out.push(`| ${i + 1} | ${cell(s.title)} | ${badge(s.status)} |`);
    });
    out.push("");
  }

  if (scenario.errorPath?.title) {
    out.push(`**Error path also covered:** ${scenario.errorPath.title}`);
    out.push("");
  }

  // Live test breakdown.
  if (live && tests.length > 0) {
    out.push("## Tests");
    out.push("");
    out.push("| Test | Result | Duration |");
    out.push("|------|--------|----------|");
    for (const t of tests) {
      const dur = typeof t.durationMs === "number" ? `${(t.durationMs / 1000).toFixed(1)}s` : "—";
      out.push(`| ${cell(t.title)} | ${badge(t.status)} | ${dur} |`);
    }
    out.push("");
  }

  // Diagnostics — short error excerpts from a failing run.
  if (live && diagnostics.length > 0) {
    out.push("## Diagnostics");
    out.push("");
    out.push("```");
    for (const d of diagnostics) out.push(d);
    out.push("```");
    out.push("");
  }

  // Environment (non-secret) the run targeted.
  const envEntries = Object.entries(env).filter(([, v]) => v);
  if (envEntries.length > 0) {
    out.push("## Environment");
    out.push("");
    out.push("| Key | Value |");
    out.push("|-----|-------|");
    for (const [k, v] of envEntries) out.push(`| ${cell(k)} | ${cell(v)} |`);
    out.push("");
  }

  // Links — CI run, artifacts.
  if (links.length > 0) {
    out.push("## Links");
    out.push("");
    for (const l of links) out.push(`- [${l.label}](${l.url})`);
    out.push("");
  }

  return out.join("\n") + "\n";
}
